'use client';

import { motion } from 'motion/react';

export interface ShakeMailIconProps {
  size?: number;
  color?: string;
  className?: string;
  isOpen?: boolean;
  unreadCount?: number;
}

export function ShakeMailIcon({
  size = 24,
  color = 'currentColor',
  className = '',
  isOpen = false,
  unreadCount = 0
}: ShakeMailIconProps) {
  const shouldShake = unreadCount > 0 && !isOpen;

  return (
    <div
      style={{
        position: 'relative',
        width: size,
        height: size
      }}
    >
      {/* Envelope + shake */}
      <motion.svg
        xmlns="http://www.w3.org/2000/svg"
        width={size}
        height={size}
        viewBox="0 0 24 24"
        fill={color}
        className={`icon icon-tabler ${className}`}
        style={{ perspective: '2000px' }}
        animate={shouldShake ? 'shake' : 'idle'}
        variants={{
          idle: { rotate: 0 },
          shake: {
            rotate: [0, -6, 6, -6, 6, 0],
            transition: {
              duration: 0.6,
              ease: 'easeInOut'
            }
          }
        }}
      >
        <path stroke="none" d="M0 0h24v24H0z" fill="none" />

        {/* Envelope body */}
        <path d="M22 7.535v9.465a3 3 0 0 1 -2.824 2.995l-.176 .005h-14a3 3 0 0 1 -2.995 -2.824l-.005 -.176v-9.465l9.445 6.297l.116 .066a1 1 0 0 0 .878 0l.116 -.066l9.445 -6.297z" />

        {/* Top flap */}
        <motion.path
          d="M19 4c1.08 0 2.027 .57 2.555 1.427l-9.555 6.37l-9.555 -6.37a2.999 2.999 0 0 1 2.354 -1.42l.201 -.007h14z"
          style={{
            transformBox: 'fill-box',
            transformOrigin: '50% 0%'
          }}
          animate={isOpen ? 'open' : 'closed'}
          variants={{
            closed: {
              rotateX: 0,
              y: 0
            },
            open: {
              rotateX: -180,
              y: -4
            }
          }}
          transition={{
            type: 'spring',
            stiffness: 300,
            damping: 20
          }}
        />
      </motion.svg>

      {/* Unread badge */}
      {unreadCount > 0 && (
        <motion.div
          initial={{ scale: 0 }}
          animate={{ scale: 1 }}
          exit={{ scale: 0 }}
          transition={{
            type: 'spring',
            stiffness: 500,
            damping: 20
          }}
          style={{
            position: 'absolute',
            top: -4,
            right: -4,
            minWidth: 16,
            height: 16,
            padding: '0 4px',
            borderRadius: 999,
            background: '#ef4444',
            color: 'white',
            fontSize: 10,
            fontWeight: 600,
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            lineHeight: 1,
            pointerEvents: 'none'
          }}
        >
          {unreadCount > 99 ? '99+' : unreadCount}
        </motion.div>
      )}
    </div>
  );
}
